  function storedLanguage(){try{return JSON.parse(localStorage.getItem('quiz-v2-settings')||'{}').language||'sk';}catch(_){return'sk';}}
  function language(){return window.QuizCore?.settings?.language||storedLanguage();}
  function tr(text,lang=language()){if(lang==='sk')return text;return UI[lang]?.[text]||text;}
  function categoryName(category,lang=language()){return category?.i18n?.[lang]||CATEGORY_NAMES[category?.id]?.[lang]||category?.name||'';}
  function localizeQuestion(question,lang=language()){
    const translation=question?.i18n?.[lang];return translation?{...question,...translation,i18n:question.i18n}:{...question};
  }
  function localizeBank(bank,lang=language()){
    const localized={...bank,categories:bank.categories.map(category=>{const questions=(lang==='sk'?category.questions:category.questions.filter(question=>question.i18n?.[lang])).map(question=>localizeQuestion(question,lang));return {...category,name:categoryName(category,lang),questions};})};
    localized.language=lang;return localized;
  }
